#!/bin/bash
# ==============================================================
# 幻觉预判器 · 7B 云端一键实验
# 目标：AutoDL RTX3090/A5000 (≥24GB VRAM, CUDA 12.x)
# 用法：bash cloud_run.sh
# ==============================================================
set -e

WORKDIR="$HOME/hallu_7b"
PKGDIR="$WORKDIR/constraint_residual/hallucination_predictor"
OUTDIR="$PKGDIR/output"

echo "============================================================="
echo " 幻觉预判器 · 7B 实验"
echo " 目标: Qwen2.5-7B-Instruct (float16, ~14GB VRAM)"
echo " 工作目录: $WORKDIR"
echo "============================================================="
echo ""

mkdir -p "$PKGDIR" "$OUTDIR"
touch "$WORKDIR/constraint_residual/__init__.py"
touch "$PKGDIR/__init__.py"

# ---- Step 0: 环境 ----
echo "[0/6] 安装依赖..."
pip install transformers torch scikit-learn huggingface_hub -q 2>&1 | tail -3
echo "  依赖安装完成"

# ---- Step 1: 解压代码 ----
echo "[1/6] 部署代码..."
python3 << 'DEPLOY'
import base64, tarfile, io, os
B64 = \"\"\"\"\"\"
data = base64.b64decode(B64)
target = os.path.expanduser(\"~/hallu_7b/constraint_residual/hallucination_predictor/\")
with tarfile.open(fileobj=io.BytesIO(data)) as tf:
    tf.extractall(path=target)
print(f\"  代码部署完成: {len(tf.getnames())} 文件\")
DEPLOY

# ---- Step 2: 下载+测试模型 ----
echo "[2/6] 下载 Qwen2.5-7B-Instruct..."
python3 << 'MODELTEST'
import os, sys, time
sys.path.insert(0, os.path.expanduser("~/hallu_7b"))
from constraint_residual.hallucination_predictor.model_wrapper import ModelWrapper
print("  Loading model...")
t0 = time.time()
w = ModelWrapper(model_name="Qwen/Qwen2.5-7B-Instruct", device="cuda")
elapsed = time.time() - t0
print(f"  加载完成: {elapsed:.0f}s")
print(f"  hidden_size={w.hidden_dim}, layers={w.num_layers}, heads={w.num_heads}")
s = w.generate_and_extract("Hello", max_new_tokens=8)
print(f"  Inference OK: '{s.generated_text[:60]}'")
import torch
if torch.cuda.is_available():
    print(f"  VRAM used: {torch.cuda.max_memory_allocated()/1e9:.1f}GB")
MODELTEST

# ---- Step 3: POC 评估 ----
echo ""
echo "[3/6] POC 评估..."
cd "$WORKDIR"
python3 -m constraint_residual.hallucination_predictor.run_poc \
    --model Qwen/Qwen2.5-7B-Instruct \
    --device cuda \
    --false-premise \
    --calibrate \
    --temperature 0.6 2>&1 | tail -50

# ---- Step 4: 进阶分析 ----
echo ""
echo "[4/6] 进阶分析 (HALT探针 + 信号对比)..."
python3 -m constraint_residual.hallucination_predictor.advanced_analysis \
    --model Qwen/Qwen2.5-7B-Instruct \
    --device cuda 2>&1 | tail -40

# ---- Step 5: 基线对比 ----
echo ""
echo "[5/6] 基线对比..."
python3 -m constraint_residual.hallucination_predictor.compare_baselines \
    --model Qwen/Qwen2.5-7B-Instruct \
    --device cuda 2>&1 | tail -40

# ---- Step 6: 学习约束 ----
echo ""
echo "[6/6] 学习约束 (A1+A2)..."
python3 -m constraint_residual.hallucination_predictor.learned_constraints \
    --model Qwen/Qwen2.5-7B-Instruct \
    --device cuda 2>&1 | tail -40

# ---- 报告 ----
echo ""
echo "[报告] 生成 HTML..."
python3 -m constraint_residual.hallucination_predictor.visualize \
    "$OUTDIR/poc_results_fp.json" \
    "$OUTDIR/advanced_analysis.json" \
    "$OUTDIR/baseline_comparison.json" \
    "$OUTDIR/learned_constraints.json" 2>&1

# ---- 打包 ----
echo ""
echo "============================================================="
echo " 全部完成！"
echo "============================================================="
ls -la "$OUTDIR/"
echo ""
TARBALL="$HOME/results_7b.tar.gz"
tar czf "$TARBALL" -C "$OUTDIR" .
ls -lh "$TARBALL"
echo ""
echo "===== 下载命令（Mac 本地执行）====="
echo "scp root@<实例IP>:$TARBALL ./results_7b.tar.gz"
echo "tar xzf results_7b.tar.gz && open poc_report.html"
